60	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
61	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
62	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
63	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
64	  // and vreg remain pass-through (read-only / too large for DM).
65	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
66	  // contribution would otherwise be discarded as the passthrough preserves
67	  // QEMU1's pre-handoff value.
68	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
69	  {
70	    auto state       = input;
71	    const auto fresh = drain();
72	    std::copy(std::begin(fresh.gpr) + 1, std::end(fresh.gpr),
73	              std::begin(state.gpr) + 1);
