1	// ABI contract for hybrid handoff state: magic/version, layout, roundtrip.
2	
3	#include "hybrid/state_abi.h"
4	
5	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
6	#include <doctest.h>
7	
8	#include <cstdint>
9	#include <cstring>
10	#include <type_traits>
11	
12	TEST_CASE("magic and version are stable wire constants")
13	{
14	  CHECK(HYBRID_STATE_MAGIC == 0x42594841u);
15	  // L11 widened vreg to 256 bytes/register, shifting every offset after it;
16	  // version 2 makes readers reject pre-L11 files loudly instead of
17	  // mis-parsing them.
18	  CHECK(HYBRID_STATE_VERSION == 2u);
19	}
20	
21	TEST_CASE("struct is standard-layout, trivially copyable, no tail padding")
22	{
23	  CHECK(std::is_standard_layout_v<hybrid_state_v1>);
24	  CHECK(std::is_trivially_copyable_v<hybrid_state_v1>);
25	  CHECK(sizeof(hybrid_state_v1) % 8 == 0);
26	}
27	
28	TEST_CASE("header field offsets")
29	{
30	  CHECK(offsetof(hybrid_state_v1, magic) == 0);
31	  CHECK(offsetof(hybrid_state_v1, version) == 4);
32	  CHECK(offsetof(hybrid_state_v1, flags) == 8);
33	  CHECK(offsetof(hybrid_state_v1, hart_id) == 12);
34	  CHECK(offsetof(hybrid_state_v1, pc) == 16);
35	  CHECK(offsetof(hybrid_state_v1, priv) == 24);
36	}
37	
38	TEST_CASE("GPR and FPR are 32 * uint64_t each, contiguous")
39	{
40	  hybrid_state_v1 s{};
41	  CHECK(offsetof(hybrid_state_v1, gpr) == 32);
42	  CHECK(sizeof(s.gpr) == 32 * sizeof(uint64_t));
43	  CHECK(offsetof(hybrid_state_v1, fpr) == 32 + 32 * 8);
44	  CHECK(sizeof(s.fpr) == 32 * sizeof(uint64_t));
45	}
46	
47	TEST_CASE("V-extension fields use compile-time MAX_VLEN constant")
48	{
49	  hybrid_state_v1 s{};
50	  CHECK(HYBRID_VLEN_BYTES_MAX >= 16);  // RVV minimum VLEN=128 -> 16 bytes
51	  CHECK((HYBRID_VLEN_BYTES_MAX & (HYBRID_VLEN_BYTES_MAX - 1)) == 0);  // power of 2
52	  CHECK(sizeof(s.vreg) == 32u * HYBRID_VLEN_BYTES_MAX);
53	}
54	
55	TEST_CASE("L11: wire format carries VLEN up to 1024 bits (vlenb 128)")
56	{
57	  hybrid_state_v1 s{};
58	  CHECK(HYBRID_VLEN_BYTES_MAX == 128);
59	  CHECK(sizeof(s.vreg) == 32u * 128u);
60	  // vreg@1320 + 32*128 data + 256 trailer (vxsat/vxrm/vcsr, warmup pair,
61	  // fcsr, reserved[208]).
62	  CHECK(sizeof(hybrid_state_v1) == 1320u + 32u * 128u + 256u);
63	}
64	
65	TEST_CASE("V CSRs vxsat/vxrm/vcsr follow vreg")
66	{
67	  CHECK(offsetof(hybrid_state_v1, vxsat)
68	        == offsetof(hybrid_state_v1, vreg) + 32u * HYBRID_VLEN_BYTES_MAX);
69	  CHECK(offsetof(hybrid_state_v1, vxrm)
70	        == offsetof(hybrid_state_v1, vxsat) + sizeof(uint64_t));
71	  CHECK(offsetof(hybrid_state_v1, vcsr)
72	        == offsetof(hybrid_state_v1, vxrm) + sizeof(uint64_t));
73	}
74	
75	TEST_CASE("L20: fcsr follows vcsr")
76	{
77	  CHECK(offsetof(hybrid_state_v1, fcsr)
78	        == offsetof(hybrid_state_v1, vcsr) + sizeof(uint64_t));
79	}
80	
81	TEST_CASE("Andes setup CSRs (mcache_ctl/mmisc_ctl) follow fcsr, before reserved")
82	{
83	  CHECK(offsetof(hybrid_state_v1, mcache_ctl)
84	        == offsetof(hybrid_state_v1, fcsr) + sizeof(uint64_t));
85	  CHECK(offsetof(hybrid_state_v1, mmisc_ctl)
86	        == offsetof(hybrid_state_v1, mcache_ctl) + sizeof(uint64_t));
87	  CHECK(offsetof(hybrid_state_v1, reserved)
88	        == offsetof(hybrid_state_v1, mmisc_ctl) + sizeof(uint64_t));
89	}
90	
91	TEST_CASE("PMP arrays are sized per spec")
92	{
93	  hybrid_state_v1 s{};
94	  CHECK(sizeof(s.pmpcfg) == HYBRID_PMP_CFG_NUM * sizeof(uint64_t));
95	  CHECK(sizeof(s.pmpaddr) == HYBRID_PMP_ADDR_NUM * sizeof(uint64_t));
96	  CHECK(HYBRID_PMP_ADDR_NUM == 64);
97	  CHECK(HYBRID_PMP_CFG_NUM == 16);
98	}
99	
100	TEST_CASE("trailing reserved padding leaves room for v1 future growth")
101	{
102	  hybrid_state_v1 s{};
103	  // 256 bytes were originally reserved; vxsat/vxrm/vcsr consume 24 of them
104	  // without changing the total struct size. The remainder must still hold
105	  // a few more uint64 slots before v2 is required.
106	  CHECK(sizeof(s.reserved) >= 64);
107	  CHECK(sizeof(s.reserved) % 8 == 0);
108	}
109	
110	TEST_CASE("byte-level roundtrip via memcpy preserves all fields")
111	{
112	  hybrid_state_v1 src{};
113	  src.magic = HYBRID_STATE_MAGIC;
114	  src.version = HYBRID_STATE_VERSION;
115	  src.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP | HYBRID_FLAG_V;
116	  src.hart_id = 1;
117	  src.pc = 0x80001234ULL;
118	  src.priv = 3;  // M-mode
119	
120	  for (int i = 0; i < 32; ++i) {
121	    src.gpr[i] = 0xCAFE0000ULL + i;
122	    src.fpr[i] = 0xF00D0000ULL + i;
123	  }
124	  src.mstatus = 0xa00040080ULL;
125	  src.mepc    = 0x80002000ULL;
126	  src.mtvec   = 0x80000000ULL;
127	  src.satp    = 0x8000000000080000ULL;
128	  src.vstart  = 0;
129	  src.vtype   = 0xc0;
130	  src.vl      = 4;
131	  src.vlenb   = 16;
132	  src.vxsat   = 1;
133	  src.vxrm    = 2;
134	  src.vcsr    = 0x5;  // vxrm[2:1] | vxsat[0]
135	  for (size_t i = 0; i < sizeof(src.vreg); ++i) src.vreg[i] = (uint8_t) i;
136	
137	  alignas(hybrid_state_v1) unsigned char buf[sizeof(hybrid_state_v1)];
138	  std::memcpy(buf, &src, sizeof(src));
139	  hybrid_state_v1 dst{};
140	  std::memcpy(&dst, buf, sizeof(dst));
141	
142	  CHECK(dst.magic == HYBRID_STATE_MAGIC);
143	  CHECK(dst.version == HYBRID_STATE_VERSION);
144	  CHECK(dst.flags == src.flags);
145	  CHECK(dst.hart_id == 1);
146	  CHECK(dst.pc == 0x80001234ULL);
147	  CHECK(dst.priv == 3);
148	  for (int i = 0; i < 32; ++i) {
149	    CHECK(dst.gpr[i] == 0xCAFE0000ULL + i);
150	    CHECK(dst.fpr[i] == 0xF00D0000ULL + i);
151	  }
152	  CHECK(dst.mstatus == 0xa00040080ULL);
153	  CHECK(dst.mepc == 0x80002000ULL);
154	  CHECK(dst.mtvec == 0x80000000ULL);
155	  CHECK(dst.satp == 0x8000000000080000ULL);
156	  CHECK(dst.vtype == 0xc0);
157	  CHECK(dst.vl == 4);
158	  CHECK(dst.vlenb == 16);
159	  CHECK(dst.vxsat == 1);
160	  CHECK(dst.vxrm == 2);
161	  CHECK(dst.vcsr == 0x5);
162	  CHECK(std::memcmp(dst.vreg, src.vreg, sizeof(src.vreg)) == 0);
163	}
164	
165	TEST_CASE("flag bits are stable wire constants")
166	{
167	  CHECK(HYBRID_FLAG_RV64 == (1u << 0));
168	  CHECK(HYBRID_FLAG_FP   == (1u << 1));
169	  CHECK(HYBRID_FLAG_V    == (1u << 2));
170	}
