139	      CHECK(hy.diffs[0].field == "mtval");
140	    }
141	    {
142	      hybrid_state_v1 got = ref;
143	      got.mie = 0xbad;
144	      const DiffReport hy = diff_states(ref, got);
145	      CHECK(hy.diffs.size() == 1);
146	      CHECK(hy.diffs[0].field == "mie");
147	    }
148	    {  // mip excluded from verify.
149	      hybrid_state_v1 got = ref;
