177	    const hybrid_state_v1 ref = base_state();
178	    hybrid_state_v1 got = ref;
179	    got.fcsr = 0;  // restore lost: vsim drained the reset value
180	    const DiffReport r = diff_states(ref, got);
181	    CHECK(r.diffs.size() == 1);
182	    CHECK(r.diffs[0].field == "fcsr");
183	  }
184	
