195	    const hybrid_state_v1 ref = base_state();
196	    hybrid_state_v1 got = ref;
197	    got.vreg[3 * HYBRID_VLEN_BYTES_MAX + 7] ^= 0xff;
198	    const DiffReport r = diff_states(ref, got);
